css:
html,body{margin:0;background:#fff;color:#202020} :root{color-scheme:light;--card-shadow:0 10px 40px rgb(0 0 0 / .065)}
.linktree-view-page,
.linktree-view-page * { box-sizing: border-box; }

.linktree-view-page {
  min-height: 100svh;
  padding: clamp(112px, 9.5vw, 198px) clamp(32px, 10vw, 208px) 144px;
  background: #fff;
  color: #202020;
  font-family: var(--font-inter, Inter), Inter, ui-sans-serif, system-ui, sans-serif;
}

.linktree-view {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  column-gap: 28px;
  row-gap: 104px;
  width: min(1656px, 100%);
  margin: 0 auto;
}

.linktree-card { min-width: 0; }
.linktree-preview-link { display: block; border-radius: 24px; }

.linktree-preview {
  position: relative;
  display: block;
  aspect-ratio: 1.49;
  overflow: hidden;
  border-radius: 24px;
  background: #f1f1f1;
  transform: translateZ(0);
  transition: background-color 180ms ease, transform 180ms ease;
}

.linktree-preview img {
  position: absolute; top: 11%; left: 11%; width: 78%; height: 78%;
  object-fit: cover; object-position: top; border-radius: 20px;
  background: white; box-shadow: var(--card-shadow);
  pointer-events: none;
}

.linktree-preview-link:hover .linktree-preview { background: #ededed; transform: translateY(-2px); }
.linktree-preview-link:active .linktree-preview { transform: translateY(0) scale(.995); }
.linktree-preview-link:focus-visible,
.linktree-title-row > :focus-visible { outline: 2px solid #969696; outline-offset: 6px; }

.linktree-title-row {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 40px;
  padding: 20px 32px 0;
}

.linktree-title-row > a,
.linktree-title-edit {
  min-width: 0;
  color: inherit;
  font-size: 16px;
  font-weight: 400;
  line-height: 24px;
  letter-spacing: -.025em;
  overflow-wrap: anywhere;
  text-decoration: none;
}

.linktree-title-edit { padding: 0; border: 0; background: transparent; text-align: left; cursor: pointer; }
.linktree-title-row > a:hover,
.linktree-title-edit:hover { color: #767676; }
.numen-title-form { display: flex; width: 100%; min-width: 0; }
.numen-title-form input { box-sizing: border-box; width: 100%; min-width: 0; height: 32px; padding: 3px 8px; border: 1px solid #d3d3d3; border-radius: 8px; background: #fff; color: #202020; font: 400 16px/24px Inter, -apple-system, BlinkMacSystemFont, 'Helvetica Neue', sans-serif; letter-spacing: -.025em; outline: 0; }
.numen-title-form input:focus { border-color: #8f8f8f; box-shadow: 0 0 0 2px rgb(0 0 0 / .06); }

.numen-create-card { min-width: 0; width: 100%; }
.numen-create-preview { display: block; width: 100%; padding: 0; border: 0; border-radius: 24px; background: transparent; color: #777; cursor: pointer; font: inherit; }
.numen-create-surface { display: grid; place-items: center; width: 100%; aspect-ratio: 1.49; border-radius: 24px; background: #f1f1f1; transition: background-color 180ms ease, transform 180ms ease; }
.numen-create-preview:hover .numen-create-surface { background: #ededed; transform: translateY(-2px); }
.numen-create-preview:active .numen-create-surface { transform: translateY(0) scale(.995); }
.numen-create-preview:focus-visible { outline: 0; }
.numen-create-plus { color: #8b8b8b; font: 300 44px/1 Inter, -apple-system, BlinkMacSystemFont, 'Helvetica Neue', sans-serif; transform: translateY(-1px); }

.numen-create-dialog { width: min(420px, calc(100vw - 40px)); padding: 26px; border: 0; border-radius: 22px; background: #fff; color: #202020; box-shadow: 0 28px 90px rgb(0 0 0 / .2); font-family: Inter, -apple-system, BlinkMacSystemFont, 'Helvetica Neue', sans-serif; }
.numen-create-dialog::backdrop { background: rgb(0 0 0 / .18); backdrop-filter: blur(2px); }
.numen-create-dialog h2 { margin: 0 0 22px; font-size: 22px; line-height: 28px; font-weight: 500; letter-spacing: -.03em; }
.numen-create-dialog label { display: block; margin-bottom: 8px; font-size: 13px; color: #666; }
.numen-create-dialog input { box-sizing: border-box; width: 100%; height: 44px; padding: 0 12px; border: 1px solid #d6d6d6; border-radius: 11px; background: #fff; color: #202020; font: 400 16px/1 Inter, -apple-system, BlinkMacSystemFont, 'Helvetica Neue', sans-serif; outline: 0; }
.numen-create-dialog input:focus { border-color: #8f8f8f; box-shadow: 0 0 0 3px rgb(0 0 0 / .06); }
.numen-create-path,
.numen-create-error { margin: 9px 0 0; font-size: 12px; line-height: 18px; color: #999; overflow-wrap: anywhere; }
.numen-create-error { color: #9b4338; }
.numen-create-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 24px; }
.numen-create-actions button { height: 38px; padding: 0 14px; border: 0; border-radius: 10px; background: #f0f0f0; color: #333; font: 500 13px/1 Inter, -apple-system, BlinkMacSystemFont, 'Helvetica Neue', sans-serif; cursor: pointer; }
.numen-create-actions button[type='submit'] { background: #202020; color: #fff; }
.numen-create-actions button:disabled { opacity: .45; cursor: default; }
@media (max-width: 1100px) {
  .linktree-view-page { padding-inline: clamp(32px, 7vw, 80px); }
  .linktree-view { grid-template-columns: repeat(2, minmax(0, 1fr)); row-gap: 88px; }
}

@media (max-width: 680px) {
  .linktree-view-page { padding: 88px 24px 96px; }
  .linktree-view { grid-template-columns: minmax(0, 1fr); row-gap: 64px; }
  .linktree-preview,
  .linktree-preview-link,
  .numen-create-preview,
  .numen-create-surface { border-radius: 20px; }
  .linktree-title-row { padding: 16px 20px 0; }
}

@media (prefers-reduced-motion: reduce) {
  .linktree-preview,
  .numen-create-surface { transition: none; }
}

/* Presentation build: stable targets and no navigation-related hover movement. */
.linktree-card[data-collection-id] { cursor: pointer; }
.linktree-card[aria-busy="true"] { cursor: progress; }
.linktree-preview, .numen-create-surface { transition: none; }
.linktree-preview-link:hover .linktree-preview,
.linktree-preview-link:active .linktree-preview,
.numen-create-preview:hover .numen-create-surface,
.numen-create-preview:active .numen-create-surface { transform: none; }

/* Direct demo covers: one large surface, two columns, or three clipped columns. */
.numen-cover-content{position:absolute;inset:12% 10%;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px 14px;align-content:start;pointer-events:none}
.numen-cover-content[data-columns="2"]{grid-template-columns:repeat(2,minmax(0,1fr));width:66%}
.numen-cover-content[data-columns="1"]{inset:12%;align-content:stretch;grid-template-rows:minmax(0,1fr);grid-template-columns:minmax(0,1fr)}
.numen-cover-tile{min-width:0;min-height:0;align-self:start;width:100%;display:block;position:relative;aspect-ratio:1.49;background:#fff;border-radius:9px;box-shadow:var(--card-shadow);overflow:hidden}
.numen-cover-content[data-columns="1"] .numen-cover-tile{height:100%;aspect-ratio:auto;border-radius:20px}
.linktree-preview .numen-cover-tile img{position:absolute;inset:0;width:100%;height:100%;border-radius:0;box-shadow:none;object-fit:var(--preview-fit,cover);object-position:var(--preview-position,top)}

.linktree-preview{container-type:inline-size}
.numen-cover-content{gap:14px;grid-auto-rows:calc((80cqw - 28px) / 4.47)}
.numen-cover-content[data-columns="2"]{grid-auto-rows:calc((66cqw - 14px) / 2.98)}
.numen-cover-content[data-columns="1"]{grid-auto-rows:auto}
.numen-cover-tile{height:100%;aspect-ratio:auto}

.numen-cover-content[data-columns="3"]{width:calc(76cqw - 13.72px);left:50%;right:auto;transform:translateX(-50%);grid-auto-rows:calc((76cqw / 1.49 - 28px) / 3)}

.numen-cover-content{gap:4.2cqw;grid-auto-rows:calc((80cqw - 8.4cqw) / 4.47)}
.numen-cover-content[data-columns="2"]{grid-auto-rows:calc((66cqw - 4.2cqw) / 2.98)}
.numen-cover-content[data-columns="3"]{width:72cqw;grid-auto-rows:calc((72cqw - 8.4cqw) / 4.47)}
.numen-cover-tile{border-radius:2.7cqw;box-shadow:0 2.5cqw 10cqw rgb(0 0 0 / .065)}

.organization-label{margin-left:10px;font-size:12px;color:#888;font-weight:400;white-space:nowrap}

.preview-marker{position:absolute;inset:0;display:grid;place-items:center;text-align:center;padding:8px;color:#777;font-size:11px;overflow-wrap:anywhere}.numen-cover-tile:has(img)>.preview-marker{visibility:hidden}

