/* One 8px spacing system for every toolbar state. */
.toolbar {
  --button-size: 32px;
  --icon-size: 18px;
  --group-gap: 8px;
  position: fixed;
  inset: 0 0 auto 0;
  z-index: 10;
  height: 64px;
  background: transparent;
  container-type: inline-size;
  box-sizing: border-box;
}
.toolbar-primary, .toolbar-secondary {
  position: absolute;
  top: 16px;
  display: flex;
  align-items: center;
  gap: var(--group-gap);
  height: var(--button-size);
}
.toolbar-primary { left: 24px; }
.toolbar-secondary { right: 24px; }
.toolbar .navigation { display: flex; align-items: center; flex: none; }
